"""Issue の本文の読み書き。マークで囲んだ範囲と見出しの節の取り出し・範囲の書き換え・本文のハッシュ値 (計画の KTD7・KTD8)。

マークは HTML のコメントで、範囲の名前ごとに開始と終了の 2 行を書く。

    <!-- issue-practice:<名前> -->
    ...
    <!-- /issue-practice:<名前> -->

範囲の名前は定数 REGIONS にあるものだけ (文書 `issue-practice/references/closing-conditions.md` の節「節の場所」と一致させる)。
マークは、その行にマークだけがある行として書く。コードブロック (``` か ~~~ で囲んだ部分) の中のマークと見出しは数えない。
本文に書式の例を書いたときに、例を範囲や節と取り違えないため。

関数は、解析できた値の辞書か、理由の文字列を持つ辞書 (`{"error": <理由>}`) を返す。例外は送出しない。
"""

import hashlib
import re

REGIONS = ("closing-conditions", "merge-plan")

_FENCE_RE = re.compile(r"^ {0,3}(```|~~~)")
_HEADING_RE = re.compile(r"^(#{1,6}) +(.*?)\s*#*\s*$")


def start_mark(name):
    return f"<!-- issue-practice:{name} -->"


def end_mark(name):
    return f"<!-- /issue-practice:{name} -->"


def body_sha256(body):
    """本文のハッシュ値 (UTF-8 の SHA-256 の 16 進数)。本文は gh が返したまま使い、改行や空白をそろえない。"""
    return hashlib.sha256((body or "").encode("utf-8")).hexdigest()


def split_lines(body):
    """本文を行に分ける。改行は `\\n` で分け、行末の `\\r` は残す (書き戻したときに元の本文に戻るように)。"""
    return (body or "").split("\n")


def outside_fences(lines):
    """コードブロックの外にある行の番号 (0 から数える) の集合。"""
    result = set()
    fence = None
    for i, line in enumerate(lines):
        m = _FENCE_RE.match(line)
        if m:
            marker = m.group(1)
            if fence is None:
                fence = marker
                continue
            if marker == fence:
                fence = None
                continue
        if fence is None:
            result.add(i)
    return result


def heading(line):
    """見出しの行なら (レベル, 文字列)、そうでなければ None。"""
    m = _HEADING_RE.match(line.rstrip("\r"))
    if not m:
        return None
    return len(m.group(1)), m.group(2).strip()


def _strip_blank(lines):
    start, end = 0, len(lines)
    while start < end and not lines[start].strip():
        start += 1
    while end > start and not lines[end - 1].strip():
        end -= 1
    return lines[start:end]


def find_region(body, name):
    """マークで囲んだ範囲を探す。

    返り値は {"name", "start_line", "end_line", "content", "lines"} か {"error"}。行番号は本文の 1 行目を 1 とし、
    start_line と end_line はマークの行。content は範囲の中の行 (前後の空行を除く) をつないだ文字列、lines は範囲の中の行の
    配列 (行番号と行の組。前後の空行も含む)。
    """
    if name not in REGIONS:
        return {"error": f"知らない範囲の名前: {name!r} (使える名前: {', '.join(REGIONS)})"}
    lines = split_lines(body)
    visible = outside_fences(lines)
    starts = [i for i in sorted(visible) if lines[i].strip() == start_mark(name)]
    ends = [i for i in sorted(visible) if lines[i].strip() == end_mark(name)]
    if not starts and not ends:
        return {"error": f"範囲 {name} のマークが無い"}
    if len(starts) > 1:
        return {"error": f"範囲 {name} の開始のマークが複数ある (行 {', '.join(str(i + 1) for i in starts)})"}
    if len(ends) > 1:
        return {"error": f"範囲 {name} の終了のマークが複数ある (行 {', '.join(str(i + 1) for i in ends)})"}
    if not starts:
        return {"error": f"範囲 {name} の開始のマークが無い (終了のマークは行 {ends[0] + 1})"}
    if not ends:
        return {"error": f"範囲 {name} が閉じていない (開始のマークは行 {starts[0] + 1})"}
    start, end = starts[0], ends[0]
    if end < start:
        return {"error": f"範囲 {name} の終了のマーク (行 {end + 1}) が開始のマーク (行 {start + 1}) より前にある"}
    inner = [(i + 1, lines[i].rstrip("\r")) for i in range(start + 1, end)]
    content = "\n".join(_strip_blank([text for _, text in inner]))
    return {"name": name, "start_line": start + 1, "end_line": end + 1, "content": content, "lines": inner}


def has_region_mark(body, name):
    """範囲の開始か終了のマークが、コードブロックの外に 1 つでもあるか。"""
    lines = split_lines(body)
    marks = (start_mark(name), end_mark(name))
    return any(lines[i].strip() in marks for i in outside_fences(lines))


def replace_region(body, name, content):
    """マークで囲んだ範囲の中を content に書き換えた本文を返す。範囲の外は 1 文字も変えない。

    範囲の中は「開始のマーク・空行・content・空行・終了のマーク」の形にする。返り値は {"body"} か {"error"}。
    """
    found = find_region(body, name)
    if "error" in found:
        return found
    lines = split_lines(body)
    start, end = found["start_line"] - 1, found["end_line"] - 1
    inner = (content or "").strip("\n").split("\n")
    new_lines = lines[:start + 1] + [""] + inner + [""] + lines[end:]
    return {"body": "\n".join(new_lines)}


def find_section(body, title, level=2):
    """見出し (レベル level、文字列 title) の節を探す。節は、次の同じレベル以上の見出しの手前まで。

    返り値は {"title", "heading_line", "end_line", "content", "lines"} か {"error"}。end_line は節の最後の行。
    """
    lines = split_lines(body)
    visible = outside_fences(lines)
    found = [i for i in sorted(visible) if heading(lines[i]) == (level, title)]
    if not found:
        return {"error": f"節「{title}」(見出しのレベル {level}) が無い"}
    if len(found) > 1:
        return {"error": f"節「{title}」が複数ある (行 {', '.join(str(i + 1) for i in found)})"}
    start = found[0]
    end = len(lines)
    for i in sorted(visible):
        if i <= start:
            continue
        h = heading(lines[i])
        if h and h[0] <= level:
            end = i
            break
    inner = [(i + 1, lines[i].rstrip("\r")) for i in range(start + 1, end)]
    content = "\n".join(_strip_blank([text for _, text in inner]))
    return {"title": title, "heading_line": start + 1, "end_line": end, "content": content, "lines": inner}

"""計画案のファイルの共通の部分。保存先の確認・ファイル名・先頭の書式の解析・本文の照合 (計画の KTD7・KTD13・KTD14)。

書式の SSOT は、文書 `issue-practice/references/draft-plan.md` とこのモジュール。計画案の中身 (スキルごとの節) は扱わない。
関数は、解析できた値の辞書か、理由を持つ辞書を返す。例外は送出しない (ファイルを開けないときの OSError を除く)。
"""

import os
import re
import subprocess

from issue_practice import bodies, refs

DRAFT_DIR = "tmp/issue-practice"

# プラグイン issue-practice のスキルの名前 (計画の KD3)。ファイル名の <スキル名> はこのどれか
SKILLS = (
    "new-issue",
    "managing-issue-plan",
    "managing-issue-run",
    "managing-issue-close",
    "working-issue",
    "release-plan",
    "release-issue-plan",
    "release-run",
    "release-close",
)

TARGET_RE = re.compile(r"^[a-z0-9][a-z0-9-]*$")
FILENAME_RE = re.compile(r"^(?P<date>[0-9]{8})-(?P<time>[0-9]{4})-(?P<rest>[a-z0-9][a-z0-9-]*)\.md$")
TITLE_RE = re.compile(r"^# 計画案: (?P<title>\S.*)$")
SOURCES_HEADING = "元にした Issue"
SOURCE_RE = re.compile(r"^- (?P<url>\S+) 本文の SHA-256: (?P<sha256>[0-9a-f]{64})$")
NONE_ITEM = "- なし"

# git を実行するときに消す環境変数。--root で渡したリポジトリだけを基準にするため (hook の中などで GIT_DIR が設定されていても)
_GIT_ENV_KEYS = ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY", "GIT_COMMON_DIR", "GIT_PREFIX")


def parse_file_name(name):
    """ファイル名を解析する。返り値は {"date", "time", "skill", "target"} か {"error"}。"""
    m = FILENAME_RE.match(name or "")
    if not m:
        return {"error": f"ファイル名が <YYYYMMDD>-<hhmm>-<スキル名>-<対象>.md の形ではない: {name!r}"}
    rest = m.group("rest")
    for skill in sorted(SKILLS, key=len, reverse=True):
        if rest.startswith(skill + "-") and TARGET_RE.match(rest[len(skill) + 1:]):
            return {"date": m.group("date"), "time": m.group("time"), "skill": skill, "target": rest[len(skill) + 1:]}
    return {"error": f"ファイル名の <スキル名>-<対象> が、スキルの名前と対象の組になっていない: {name!r}"}


def file_name(skill, target, stamp):
    """ファイル名を作る。stamp は `YYYYMMDD-hhmm`。返り値は {"file_name"} か {"error"}。"""
    if skill not in SKILLS:
        return {"error": f"知らないスキルの名前: {skill!r}"}
    if not TARGET_RE.match(target or ""):
        return {"error": f"対象は英小文字・数字・ハイフンで書く: {target!r}"}
    name = f"{stamp}-{skill}-{target}.md"
    parsed = parse_file_name(name)
    if "error" in parsed:
        return parsed
    return {"file_name": name}


def _git(root, *args):
    env = {k: v for k, v in os.environ.items() if k not in _GIT_ENV_KEYS}
    try:
        completed = subprocess.run(["git", "-C", root, *args], capture_output=True, text=True, env=env,
                                   stdin=subprocess.DEVNULL)
    except OSError as e:
        return {"args": ["git", "-C", root, *args], "exit_code": None, "stdout": "", "stderr": f"git を起動できない: {e}"}
    return {"args": ["git", "-C", root, *args], "exit_code": completed.returncode, "stdout": completed.stdout,
            "stderr": completed.stderr}


def check_dir(root):
    """計画案のディレクトリ (root の tmp/issue-practice/) が git に無視されているかを確かめる。

    root は、リポジトリのルートの絶対パス。返り値は次のどれか。
      {"status": "ok", "dir": <絶対パス>}
      {"status": "unsatisfied", "errors": [<理由>]}   root がルートでない・無視されていない
      {"status": "git_failed", "git_error": {...}}     git が失敗した (リポジトリでないなど)
    """
    if not root or not os.path.isabs(root):
        return {"status": "unsatisfied", "errors": [f"--root はリポジトリのルートの絶対パスで渡す: {root!r}"]}
    top = _git(root, "rev-parse", "--show-toplevel")
    if top["exit_code"] != 0:
        return {"status": "git_failed", "git_error": top}
    if os.path.realpath(top["stdout"].strip()) != os.path.realpath(root):
        return {"status": "unsatisfied",
                "errors": [f"--root がリポジトリのルートではない (ルートは {top['stdout'].strip()})"]}
    ignored = _git(root, "check-ignore", "-q", "--", DRAFT_DIR + "/")
    if ignored["exit_code"] == 1:
        return {"status": "unsatisfied",
                "errors": [f"ディレクトリ {DRAFT_DIR}/ が git に無視されていない。.gitignore に tmp/ を足してコミットしてから、"
                           "もう一度実行する (スキルは .gitignore を変えない)"]}
    if ignored["exit_code"] != 0:
        return {"status": "git_failed", "git_error": ignored}
    return {"status": "ok", "dir": os.path.join(root, DRAFT_DIR)}


def new_path(root, skill, target, stamp):
    """新しい計画案のパスを決め、ディレクトリを作る。既にあるファイルの名前は返さない。

    返り値は check_dir と同じ形で、ok のときは {"status": "ok", "path", "relative", "file_name"}。
    """
    name = file_name(skill, target, stamp)
    if "error" in name:
        return {"status": "unsatisfied", "errors": [name["error"]]}
    checked = check_dir(root)
    if checked["status"] != "ok":
        return checked
    path = os.path.join(checked["dir"], name["file_name"])
    if os.path.lexists(path):
        return {"status": "unsatisfied",
                "errors": [f"計画案のファイルが既にある (上書きしない): {path}。時刻か対象を変えて作り直す"]}
    os.makedirs(checked["dir"], exist_ok=True)
    return {"status": "ok", "path": path, "relative": f"{DRAFT_DIR}/{name['file_name']}", "file_name": name["file_name"]}


def parse(text, name):
    """計画案の先頭の書式を解析する。name はファイル名 (ディレクトリを含まない)。

    返り値は {"file_name", "title", "skill", "target", "created", "sources", "sections", "errors"}。errors は
    {"line" (1 から数える行番号。行に結び付かない誤りは null), "message"} の配列で、空なら形どおり。
    sources は {"issue" (owner/repo#番号), "url", "sha256", "line"} の配列、sections は節「元にした Issue」の後の
    レベル 2 の節 {"title", "line"} の配列。
    """
    errors = []
    result = {"file_name": name, "title": None, "skill": None, "target": None, "created": None, "sources": [],
              "sections": [], "errors": errors}
    parsed_name = parse_file_name(name)
    if "error" in parsed_name:
        errors.append({"line": None, "message": parsed_name["error"]})
    else:
        result.update(skill=parsed_name["skill"], target=parsed_name["target"],
                      created=f"{parsed_name['date'][:4]}-{parsed_name['date'][4:6]}-{parsed_name['date'][6:]} "
                              f"{parsed_name['time'][:2]}:{parsed_name['time'][2:]}")
    lines = bodies.split_lines(text)
    visible = bodies.outside_fences(lines)
    m = TITLE_RE.match(lines[0].rstrip("\r")) if lines else None
    if not m:
        errors.append({"line": 1, "message": "1 行目が「# 計画案: <題>」ではない"})
    else:
        result["title"] = m.group("title").strip()
    level2 = [(i, bodies.heading(lines[i])[1]) for i in sorted(visible)
              if bodies.heading(lines[i]) and bodies.heading(lines[i])[0] == 2]
    source_headings = [i for i, title in level2 if title == SOURCES_HEADING]
    if not source_headings:
        errors.append({"line": None, "message": f"節「{SOURCES_HEADING}」(## {SOURCES_HEADING}) が無い"})
        return result
    if len(source_headings) > 1:
        errors.append({"line": source_headings[1] + 1, "message": f"節「{SOURCES_HEADING}」が複数ある"})
    start = source_headings[0]
    if level2[0][0] != start:
        errors.append({"line": start + 1, "message": f"節「{SOURCES_HEADING}」が最初のレベル 2 の見出しではない"})
    following = [i for i, _ in level2 if i > start]
    end = following[0] if following else len(lines)
    result["sections"] = [{"title": title, "line": i + 1} for i, title in level2 if i > start]
    items, has_none, seen = [], False, {}
    for i in range(start + 1, end):
        line = lines[i].rstrip("\r")
        if not line.strip():
            continue
        if line == NONE_ITEM:
            has_none = True
            items.append(i)
            continue
        sm = SOURCE_RE.match(line)
        if not sm:
            errors.append({"line": i + 1, "message": "「- <Issue の URL> 本文の SHA-256: <64 桁の 16 進数>」か「- なし」ではない"})
            continue
        ref = refs.parse_ref(sm.group("url"))
        if "error" in ref or not sm.group("url").startswith("https://"):
            errors.append({"line": i + 1, "message": f"Issue か PR の URL ではない: {sm.group('url')}"})
            continue
        key = ref["key"].lower()
        if key in seen:
            errors.append({"line": i + 1, "message": f"同じ Issue が 2 回ある (行 {seen[key]})"})
            continue
        seen[key] = i + 1
        items.append(i)
        result["sources"].append({"issue": ref["key"], "url": ref["url"], "sha256": sm.group("sha256"), "line": i + 1})
    if not items:
        errors.append({"line": start + 1, "message": f"節「{SOURCES_HEADING}」に項目が無い (無ければ「- なし」と書く)"})
    elif has_none and result["sources"]:
        errors.append({"line": start + 1, "message": "「- なし」と Issue の項目が両方ある"})
    return result


def read(path):
    """計画案のファイルを読んで parse する。ファイルを開けなければ OSError を送出する。"""
    with open(path, encoding="utf-8") as f:
        text = f.read()
    return parse(text, os.path.basename(path))


def compare(sources):
    """節「元にした Issue」の Issue の本文を読み直し、ハッシュ値を比べる。

    返り値は {"results": [{"issue", "url", "sha256_draft", "sha256_now", "changed", "updated_at"}], "gh_error"}。
    gh が失敗したら、そこで止めて gh_error に失敗した gh の結果を入れる (残りは読まない)。
    """
    results = []
    for source in sources:
        ref = refs.parse_ref(source["url"])
        issue, failure = bodies.fetch_issue(ref)
        if failure:
            return {"results": results, "gh_error": failure}
        results.append({"issue": source["issue"], "url": source["url"], "sha256_draft": source["sha256"],
                        "sha256_now": issue["sha256"], "changed": issue["sha256"] != source["sha256"],
                        "updated_at": issue["updated_at"]})
    return {"results": results, "gh_error": None}

"""記録のコメントの 1 行目の生成と解析、Issue のコメントの一覧から記録を集めること (計画の KTD4・KTD5)。

形の SSOT は、文書 `issue-practice/references/record-comments.md` とこのモジュールの定数 KINDS・KEYS。
テスト (ファイル `issue-practice/tests/test_docs.py`) が、文書の表と定数が一致することを確認する。

関数は、解析できた値の辞書か、理由の配列を持つ辞書 (`{"errors": [...]}`) を返す。例外は送出しない。
"""

import datetime
import re

from issue_practice import draft, gh, refs

PREFIX = "issue-practice:"

# 種類ごとの必須のキーと任意のキー。where は書く場所 (comment: 記録のコメントの 1 行目、body: 作る Issue の本文の末尾の行)。
# 順序は文書の表の順で、records format はこの順にキーを並べる
KINDS = {
    "session": {"required": ("role", "session"), "optional": ("branch", "previous"), "where": "comment"},
    "approval": {"required": ("draft",), "optional": (), "where": "comment"},
    "plan-change": {"required": (), "optional": ("draft",), "where": "comment"},
    "report": {"required": ("type",), "optional": ("pr",), "where": "comment"},
    "draft-removed": {"required": ("date",), "optional": ("draft",), "where": "comment"},
    "current-swap": {"required": ("date",), "optional": ("old",), "where": "comment"},
    "release-start": {"required": (), "optional": (), "where": "comment"},
    "dependency-resolved": {"required": ("issue",), "optional": (), "where": "comment"},
    "close-check": {"required": ("result",), "optional": (), "where": "comment"},
    "abandon": {"required": ("session",), "optional": (), "where": "comment"},
    "created-from": {"required": ("draft", "key"), "optional": (), "where": "body"},
}

ROLES = ("managing", "working", "self-managing")
REPORT_TYPES = ("pr", "check", "split", "condition-change", "carve-out", "suspend")
RESULTS = ("pass", "fail")

_SESSION_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]*$")
_BRANCH_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._/-]*$")
_KEY_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*$")
_KIND_RE = re.compile(r"^[a-z][a-z-]*$")
_PAIR_RE = re.compile(r"^(?P<key>[a-z][a-z-]*)=(?P<value>.*)$")


def _enum(values):
    def check(value):
        return None if value in values else f"{' / '.join(values)} のどれか"
    return check


def _pattern(regex, description):
    def check(value):
        return None if regex.match(value) else description
    return check


def _branch(value):
    if not _BRANCH_RE.match(value) or ".." in value:
        return "英数字で始まり、英数字・.・_・/・- が続くブランチの名前 (.. を含まない)"
    return None


def _draft(value):
    parsed = draft.parse_file_name(value)
    return parsed["error"] if "error" in parsed else None


def _date(value):
    try:
        datetime.date.fromisoformat(value)
    except ValueError:
        return "YYYY-MM-DD の日付"
    return None if re.match(r"^[0-9]{4}-[0-9]{2}-[0-9]{2}$", value) else "YYYY-MM-DD の日付"


def _issue(value):
    parsed = refs.parse_ref(value)
    if "error" in parsed or value.startswith("https://") or value.isdigit():
        return "#番号 か owner/repo#番号 の Issue の参照"
    return None


def _pr_url(value):
    parsed = refs.parse_ref(value)
    if "error" in parsed or parsed["kind"] != "pull":
        return "PR の URL (https://github.com/<owner>/<repo>/pull/<番号>)"
    return None


# キーごとの値の検査。値が形どおりなら None、違えば期待する形の説明を返す
KEYS = {
    "role": _enum(ROLES),
    "session": _pattern(_SESSION_RE, "英数字で始まり、英数字・_・.・- が続くセッションの ID"),
    "previous": _pattern(_SESSION_RE, "英数字で始まり、英数字・_・.・- が続くセッションの ID"),
    "branch": _branch,
    "draft": _draft,
    "type": _enum(REPORT_TYPES),
    "pr": _pr_url,
    "date": _date,
    "old": _issue,
    "issue": _issue,
    "result": _enum(RESULTS),
    "key": _pattern(_KEY_RE, "英数字で始まり、英数字・.・_・- が続くキー"),
}


def _check(kind, values, where):
    """種類と値を検査し、誤りの配列を返す。"""
    errors = []
    spec = KINDS.get(kind)
    if spec is None:
        return [f"知らない種類: {kind!r}"]
    if where is not None and spec["where"] != where:
        place = "Issue の本文の末尾の行" if spec["where"] == "body" else "記録のコメントの 1 行目"
        errors.append(f"種類 {kind} は{place}だけで使う")
    allowed = spec["required"] + spec["optional"]
    for key in values:
        if key not in allowed:
            errors.append(f"種類 {kind} に知らないキー: {key!r} (書けるキー: {', '.join(allowed) or 'なし'})")
    for key in spec["required"]:
        if key not in values:
            errors.append(f"種類 {kind} の必須のキーが無い: {key}")
    for key, value in values.items():
        if key not in allowed:
            continue
        if not value or any(c.isspace() for c in value):
            errors.append(f"キー {key} の値が空か、空白を含む")
            continue
        problem = KEYS[key](value)
        if problem:
            errors.append(f"キー {key} の値 {value!r} が {problem} ではない")
    return errors


def format_line(kind, values, where=None):
    """1 行目を作る。values はキーと値の辞書。返り値は {"line"} か {"errors"}。キーは KINDS の順に並べる。"""
    errors = _check(kind, values, where)
    if errors:
        return {"errors": errors}
    spec = KINDS[kind]
    parts = [PREFIX, kind] + [f"{key}={values[key]}" for key in spec["required"] + spec["optional"] if key in values]
    return {"line": " ".join(parts)}


def is_record_line(line):
    return (line or "").startswith(PREFIX)


def parse_line(line, where=None):
    """1 行目を解析する。返り値は {"kind", "values"} か {"errors"}。where を渡すと、その場所で使える種類かも検査する。"""
    line = (line or "").rstrip("\r")
    if not is_record_line(line):
        return {"errors": [f"{PREFIX} で始まらない"]}
    tokens = line[len(PREFIX):].split()
    if not tokens:
        return {"errors": ["種類が無い"]}
    kind, errors, values = tokens[0], [], {}
    if not _KIND_RE.match(kind):
        return {"errors": [f"種類の形ではない: {kind!r}"]}
    for token in tokens[1:]:
        m = _PAIR_RE.match(token)
        if not m:
            errors.append(f"<キー>=<値> の形ではない: {token!r}")
            continue
        if m.group("key") in values:
            errors.append(f"同じキーが 2 回ある: {m.group('key')}")
            continue
        values[m.group("key")] = m.group("value")
    errors += _check(kind, values, where)
    if errors:
        return {"errors": errors}
    return {"kind": kind, "values": values}


def parse_assignments(items):
    """`<キー>=<値>` の文字列の配列を辞書にする。返り値は ({キー: 値}, 誤りの配列)。"""
    values, errors = {}, []
    for item in items:
        m = _PAIR_RE.match(item)
        if not m:
            errors.append(f"<キー>=<値> の形ではない: {item!r}")
        elif m.group("key") in values:
            errors.append(f"同じキーが 2 回ある: {m.group('key')}")
        else:
            values[m.group("key")] = m.group("value")
    return values, errors


def _split_body(body):
    first, _, rest = (body or "").partition("\n")
    return first.rstrip("\r"), rest.lstrip("\r\n")


def collect(comments, login):
    """コメントの配列 (REST の issue comment の形) から記録を集める。

    投稿者 (user.login) が login と違うコメントと、1 行目が PREFIX で始まらないコメントは除く。ログインは大文字と小文字を
    区別しない。返り値は {"records", "invalid", "skipped_other_authors"}。records の要素は
    {"kind", "values", "id", "url", "created_at", "updated_at", "body"} (body は 1 行目と続く空行を除いた本文)、
    invalid の要素は {"id", "url", "line", "errors"}。
    """
    records, invalid, skipped = [], [], 0
    for comment in comments:
        author = ((comment.get("user") or {}).get("login") or "")
        if author.lower() != (login or "").lower():
            if is_record_line(_split_body(comment.get("body"))[0]):
                skipped += 1
            continue
        first, rest = _split_body(comment.get("body"))
        if not is_record_line(first):
            continue
        parsed = parse_line(first, where="comment")
        base = {"id": comment.get("id"), "url": comment.get("html_url")}
        if "errors" in parsed:
            invalid.append({**base, "line": first, "errors": parsed["errors"]})
            continue
        records.append({"kind": parsed["kind"], "values": parsed["values"], **base,
                        "created_at": comment.get("created_at"), "updated_at": comment.get("updated_at"), "body": rest})
    return {"records": records, "invalid": invalid, "skipped_other_authors": skipped}


def fetch_comments(ref):
    """Issue (か PR) のコメントを、投稿の順に全部読む。返り値は (コメントの配列, None) か (None, 失敗した gh の結果)。"""
    result = gh.run(["api", f"repos/{ref['owner']}/{ref['repo']}/issues/{ref['number']}/comments", "--paginate", "--slurp"],
                    expect_json=True)
    if gh.failed(result):
        return None, result
    pages = result["json"]
    if not isinstance(pages, list) or not all(isinstance(p, list) for p in pages):
        return None, {**result, "json_error": "応答がページの配列 (--slurp の形) ではない"}
    return [c for page in pages for c in page if isinstance(c, dict)], None


def list_records(ref):
    """Issue の記録を集める。返り値は ({"login", "records", "invalid", "skipped_other_authors"}, None) か
    (None, 失敗した gh の結果)。"""
    login, failure = gh.viewer_login()
    if failure:
        return None, failure
    comments, failure = fetch_comments(ref)
    if failure:
        return None, failure
    return {"login": login, **collect(comments, login)}, None

#!/usr/bin/env python3
"""文書とコードの定数・入口の --help が一致することのテスト。

- 文書 `issue-practice/references/record-comments.md` の種類とキーの表が、モジュール records の定数と一致する (計画の KTD4)
"""

import os
import re
import unittest

from fakegh_case import HERE

from issue_practice import records  # noqa: E402

REFERENCES = os.path.join(HERE, "..", "references")


def read_reference(name):
    with open(os.path.join(REFERENCES, name), encoding="utf-8") as f:
        return f.read()


def table_rows(text, header):
    """見出し行が header で始まる Markdown の表の、データの行 (セルの配列) を返す。"""
    rows, inside = [], False
    for line in text.splitlines():
        if line.startswith(header):
            inside = True
            continue
        if inside:
            if not line.startswith("|"):
                inside = False
                continue
            if set(line.replace("|", "").strip()) <= {"-", " "}:
                continue
            rows.append([cell.strip() for cell in line.strip().strip("|").split("|")])
    return rows


def keys_in(cell):
    return tuple(re.findall(r"`([a-z-]+)`", cell)) if cell != "なし" else ()


class RecordCommentsDocTest(unittest.TestCase):

    def setUp(self):
        self.doc = read_reference("record-comments.md")

    def test_kinds_table_matches_constants(self):
        rows = table_rows(self.doc, "| 種類 | 必須のキー | 任意のキー |")
        documented = {}
        for cells in rows:
            kind = re.fullmatch(r"`([a-z-]+)`", cells[0]).group(1)
            self.assertNotIn(kind, documented, f"種類 {kind} が表に 2 回ある")
            documented[kind] = {"required": keys_in(cells[1]), "optional": keys_in(cells[2])}
        expected = {kind: {"required": spec["required"], "optional": spec["optional"]} for kind, spec in records.KINDS.items()}
        self.assertEqual(documented, expected, "文書の種類の表と records.KINDS が一致すること (キーの順序も)")

    def test_keys_table_matches_constants(self):
        rows = table_rows(self.doc, "| キー | 値 |")
        documented = [re.fullmatch(r"`([a-z-]+)`", cells[0]).group(1) for cells in rows]
        self.assertEqual(sorted(documented), sorted(records.KEYS), "文書のキーの表と records.KEYS が一致すること")
        values = dict(zip(documented, (cells[1] for cells in rows)))
        for name, allowed in (("role", records.ROLES), ("type", records.REPORT_TYPES), ("result", records.RESULTS)):
            with self.subTest(key=name):
                self.assertEqual(tuple(re.findall(r"`([a-z-]+)`", values[name])), allowed, f"キー {name} の値の一覧")

    def test_prefix_and_body_line(self):
        self.assertIn(f"{records.PREFIX} <種類> <キー>=<値>", self.doc)
        self.assertIn(f"{records.PREFIX} created-from draft=<計画案のファイル名> key=<計画案の中のキー>", self.doc)
        body_kinds = [k for k, spec in records.KINDS.items() if spec["where"] == "body"]
        self.assertEqual(body_kinds, ["created-from"])


if __name__ == "__main__":
    unittest.main()

"""節「クローズ条件」のチェックボックスと根拠のリンクの解析 (計画の KTD9)。

書式の SSOT は、文書 `issue-practice/references/closing-conditions.md` とこのモジュール。
範囲の決め方: 本文にマーク closing-conditions が 1 つでもあればマークで囲んだ範囲 (管理 Issue)、無ければ見出し
`## クローズ条件` の節 (作業 Issue と自己管理 Issue)。

関数は、解析できた値の辞書か、理由を持つ辞書 (`{"error": <理由>}`) を返す。例外は送出しない。
"""

import re

from issue_practice import bodies

SECTION_TITLE = "クローズ条件"
REGION = "closing-conditions"

STATES = ("unchecked", "checked", "checked_without_evidence", "carved_out")
SATISFIED = ("checked", "carved_out")

_ITEM_RE = re.compile(r"^(?P<indent>[ \t]*)[-*+] \[(?P<mark>[ xX])\] (?P<text>.*)$")
_LINK_RE = re.compile(r"\s*\((?P<label>根拠|切り出し): (?P<url>https://\S+)\)\s*$")
_GROUPS = (("expected", "期待する状態"), ("verification", "確認するポイント"))


def find(body):
    """クローズ条件の範囲を決める。返り値は {"source" (region・section), "lines" ([(行番号, 行)])} か {"error"}。"""
    if bodies.has_region_mark(body, REGION):
        found = bodies.find_region(body, REGION)
        source = "region"
    else:
        found = bodies.find_section(body, SECTION_TITLE)
        source = "section"
    if "error" in found:
        return found
    return {"source": source, "lines": found["lines"]}


def _group(line):
    stripped = line.strip()
    h = bodies.heading(stripped)
    text = h[1] if h else stripped
    text = text.rstrip(":：").strip()
    for key, label in _GROUPS:
        if text == label:
            return key
    return None


def _indent_width(indent):
    return len(indent.expandtabs(4))


def parse_lines(lines):
    """範囲の行 ([(行番号, 行)]) からチェックボックスの項目を読む。コードブロックの中の行は読まない。

    返り値は項目の配列。項目は {"line", "text" (末尾のリンクを除いた文), "raw" (行のまま), "checked", "state",
    "evidence" (根拠の URL か None), "carved_out" (切り出しの URL か None), "group" (expected・verification・None),
    "heading" (直前のレベル 3 以上の見出しか None), "indent", "details" (項目の下の、より深い字下げの行の配列)}。
    """
    texts = [text for _, text in lines]
    visible = bodies.outside_fences(texts)
    items, group, heading_text, current = [], None, None, None
    for index, (number, text) in enumerate(lines):
        if index not in visible:
            continue
        m = _ITEM_RE.match(text)
        if m:
            checked = m.group("mark") != " "
            body_text = m.group("text")
            link = _LINK_RE.search(body_text)
            evidence = carved = None
            if link:
                body_text = body_text[:link.start()]
                if link.group("label") == "根拠":
                    evidence = link.group("url")
                else:
                    carved = link.group("url")
            if not checked:
                state = "unchecked"
            elif carved:
                state = "carved_out"
            elif evidence:
                state = "checked"
            else:
                state = "checked_without_evidence"
            current = {"line": number, "text": body_text.strip(), "raw": text, "checked": checked, "state": state,
                       "evidence": evidence, "carved_out": carved, "group": group, "heading": heading_text,
                       "indent": _indent_width(m.group("indent")), "details": []}
            items.append(current)
            continue
        h = bodies.heading(text)
        if h and h[0] >= 3:
            heading_text, current = h[1], None
            g = _group(text)
            if g:
                group = g
            continue
        g = _group(text)
        if g:
            group, current = g, None
            continue
        if current is not None and text.strip():
            if _indent_width(text[:len(text) - len(text.lstrip())]) > current["indent"]:
                current["details"].append(text.strip())
            else:
                current = None
    return items


def summarize(items):
    """項目の状態ごとの数と、満たさない項目の行番号の配列。"""
    counts = {state: 0 for state in STATES}
    for item in items:
        counts[item["state"]] += 1
    return {"counts": counts, "unsatisfied": [item["line"] for item in items if item["state"] not in SATISFIED]}


def parse(body):
    """本文のクローズ条件を読む。返り値は {"source", "items", "summary"} か {"error"}。"""
    found = find(body)
    if "error" in found:
        return found
    items = parse_lines(found["lines"])
    return {"source": found["source"], "items": items, "summary": summarize(items)}

